head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[inputCalendar > P > caption]<br/>웹접근성 향상을 위해 팝업 달력의 caption 요소에 추가 정보를 설정합니다.",
    "validation" : [
        "caption 요소에 표시할 추가 정보를 텍스트로 설정합니다.",
        "값을 설정하지 않으면 '달력' 으로 적용됩니다.",
        "팝업 달력의 가운데 요일/날짜 영역은 table 태그로 렌더링되며 caption 속성값은 table 태그의 자식 요소로 추가됩니다.",
    ]
}



scwin.onpageload = function () {
    wf_body_left.getObj("scwin").createValidation(scwin.tData);	

    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    let properties = {
        caption : con_caption.getText(),        
    }

    let cList = $c.gcm.createCList(properties);
    let eList = $c.gcm.createEList(["onclick"]);

    $c.gcm.createLabel('label="caption 설정 후 버튼 영역 클릭하여 확인"', '', 'label1');
    $c.gcm.createBasicInputCalendar(cList, eList); 
}



scwin.target1_onclick = function (e) {
    setTimeout(() => {
        let targetElement = document.querySelector('div[id*="target1_calendar"]');

        if (targetElement) {
            let caption = document.querySelector('caption[class*="w2blind"]');

            if (caption) {    
                wf_body_bottom.getObj("scwin").setReturnValue("caption : " + caption.textContent)
            }
        }
        else {
            wf_body_bottom.getObj("scwin").setReturnValue("팝업 달력을 한번 오픈해야 정보 가져올 수 있음");
        }
    }, 100);    
}
